INSERT INTO moves VALUES(97,'찌릿찌릿일렉','Buzzy Buzz','전기','Electric','Special',60,100,20,0,'normal','Has a 100% chance to paralyze the foe.',0);
INSERT INTO moves VALUES(98,'명상','Calm Mind','에스퍼','Psychic','Status',0,NULL,20,0,'self','Raises the user''s Special Attack and Special Defense by 1 stage.',1);
INSERT INTO moves VALUES(99,'보호색','Camouflage','노말','Normal','Status',0,1,20,0,'self','The user''s type changes based on the battle terrain. Normal type on the regular Wi-Fi terrain, Electric type during Electric Terrain, Fairy type during Misty Terrain, Grass type during Grassy Terrain, and Psychic type during Psychic Terrain. Fails if the user''s type cannot be changed or if the user is already purely that type.',0);
INSERT INTO moves VALUES(100,'유혹','Captivate','노말','Normal','Status',0,100,20,0,'allAdjacentFoes','Lowers the target''s Special Attack by 2 stages. The target is unaffected if both the user and the target are the same gender, or if either is genderless. Pokemon with the Oblivious Ability are immune.',0);
INSERT INTO moves VALUES(101,NULL,'Ceaseless Edge','악','Dark','Physical',65,90,16,0,'normal','If this move is successful, it sets up a hazard on the opposing side of the field, damaging each opposing Pokemon that switches in, unless it is a Flying-type Pokemon or has the Levitate Ability. A maximum of three layers may be set, and opponents lose 1/8 of their maximum HP with one layer, 1/6 of their maximum HP with two layers, and 1/4 of their maximum HP with three layers, all rounded down. Can be removed from the opposing side if any Pokemon uses Tidy Up, or if any opposing Pokemon uses Mortal Spin, Rapid Spin, or Defog successfully, or is hit by Defog.',1);
INSERT INTO moves VALUES(102,'축하','Celebrate','노말','Normal','Status',0,1,40,0,'self','No competitive use.',0);
INSERT INTO moves VALUES(103,'충전','Charge','전기','Electric','Status',0,NULL,20,0,'self','Raises the user''s Special Defense by 1 stage. The user''s next Electric-type attack will have its power doubled; the effect ends when the user is no longer active, or after the user attempts to use any Electric-type move besides Charge, even if it is not successful.',1);
