INSERT INTO moves VALUES(108,NULL,'Chilly Reception','얼음','Ice','Status',0,NULL,12,0,'all','For 5 turns, the weather becomes Snow. The user switches out even if it is trapped and is replaced immediately by a selected party member. The user does not switch out if there are no unfainted party members.',1);
