INSERT INTO moves VALUES(157,'다이아스톰','Diamond Storm','바위','Rock','Physical',100,95,5,0,'allAdjacentFoes','Has a 50% chance to raise the user''s Defense by 2 stages.',0);
INSERT INTO moves VALUES(158,'구멍파기','Dig','땅','Ground','Physical',80,100,12,0,'normal','This attack charges on the first turn and executes on the second. On the first turn, the user avoids all attacks other than Earthquake and Magnitude but takes double damage from them, and is also unaffected by weather. If the user is holding a Power Herb, the move completes in one turn.',1);
