INSERT INTO moves VALUES(344,'가위자르기','Guillotine','노말','Normal','Physical',0,30,8,0,'normal','Deals damage to the target equal to the target''s maximum HP. Ignores accuracy and evasiveness modifiers. This attack''s accuracy is equal to (user''s level - target''s level + 30)%, and fails if the target is at a higher level. Pokemon with the Sturdy Ability are immune.',1);
INSERT INTO moves VALUES(345,'더스트슈트','Gunk Shot','독','Poison','Physical',120,80,8,0,'normal','Has a 30% chance to poison the target.',1);
INSERT INTO moves VALUES(346,'바람일으키기','Gust','비행','Flying','Special',40,100,35,0,'any','Power doubles if the target is using Bounce, Fly, or Sky Drop, or is under the effect of Sky Drop.',0);
INSERT INTO moves VALUES(347,'자이로볼','Gyro Ball','강철','Steel','Physical',0,100,8,0,'normal','Power is equal to (25 * target''s current Speed / user''s current Speed) + 1, rounded down, but not more than 150. If the user''s current Speed is 0, this move''s power is 1.',1);
INSERT INTO moves VALUES(348,'싸라기눈','Hail','얼음','Ice','Status',0,1,10,0,'all','For 5 turns, the weather becomes Hail. At the end of each turn except the last, all active Pokemon lose 1/16 of their maximum HP, rounded down, unless they are an Ice type or have the Ice Body, Magic Guard, Overcoat, or Snow Cloak Abilities. Lasts for 8 turns if the user is holding Icy Rock. Fails if the current weather is Hail.',0);
