INSERT INTO moves VALUES(356,'박치기','Headbutt','노말','Normal','Physical',70,100,15,0,'normal','Has a 30% chance to make the target flinch.',0);
INSERT INTO moves VALUES(357,NULL,'Headlong Rush','땅','Ground','Physical',120,100,8,0,'normal','Lowers the user''s Defense and Special Defense by 1 stage.',1);
INSERT INTO moves VALUES(358,'치료방울','Heal Bell','노말','Normal','Status',0,NULL,8,0,'allyTeam','Every Pokemon in the user''s party is cured of its non-volatile status condition. Active Pokemon with the Soundproof Ability are not cured, unless they are the user.',1);
INSERT INTO moves VALUES(359,'회복봉인','Heal Block','에스퍼','Psychic','Status',0,100,15,0,'allAdjacentFoes','For 5 turns, the target is prevented from restoring any HP as long as it remains active. During the effect, healing and draining moves are unusable, and Abilities and items that grant healing will not heal the user. If an affected Pokemon uses Baton Pass, the replacement will remain unable to restore its HP. Pain Split and the Regenerator Ability are unaffected.',0);
INSERT INTO moves VALUES(360,'회복지령','Heal Order','벌레','Bug','Status',0,1,10,0,'self','The user restores 1/2 of its maximum HP, rounded half up.',0);
INSERT INTO moves VALUES(361,'치유파동','Heal Pulse','에스퍼','Psychic','Status',0,NULL,12,0,'any','The target restores 1/2 of its maximum HP, rounded half up. If the user has the Mega Launcher Ability, the target instead restores 3/4 of its maximum HP, rounded half down.',1);
INSERT INTO moves VALUES(362,'치유소원','Healing Wish','에스퍼','Psychic','Status',0,NULL,12,0,'self','The user faints, and if the Pokemon brought out to replace it does not have full HP or has a non-volatile status condition, its HP is fully restored along with having any non-volatile status condition cured. The replacement is sent out at the end of the turn, and the healing happens before hazards take effect. This effect continues until a Pokemon that meets either of these conditions switches in at the user''s position or gets swapped into the position with Ally Switch. Fails if the user is the last unfainted Pokemon in its party.',1);
