INSERT INTO moves VALUES(464,NULL,'Lunar Blessing','에스퍼','Psychic','Status',0,1,5,0,'allies','Each Pokemon on the user''s side restores 1/4 of its maximum HP, rounded half up, and has its status condition cured.',0);
INSERT INTO moves VALUES(465,'초승달춤','Lunar Dance','에스퍼','Psychic','Status',0,1,10,0,'self','The user faints, and if the Pokemon brought out to replace it does not have full HP or PP, or has a non-volatile status condition, its HP and PP are fully restored along with having any non-volatile status condition cured. The replacement is sent out at the end of the turn, and the healing happens before hazards take effect. This effect continues until a Pokemon that meets any of these conditions switches in at the user''s position or gets swapped into the position with Ally Switch. Fails if the user is the last unfainted Pokemon in its party.',0);
INSERT INTO moves VALUES(466,'덤벼들기','Lunge','벌레','Bug','Physical',80,100,16,0,'normal','Has a 100% chance to lower the target''s Attack by 1 stage.',1);
