INSERT INTO moves VALUES(581,'분진','Powder','벌레','Bug','Status',0,100,20,1,'normal','If the target uses a Fire-type move this turn, it is prevented from executing and the target loses 1/4 of its maximum HP, rounded half up. This effect does not happen if the Fire-type move is prevented by Primordial Sea.',0);
INSERT INTO moves VALUES(582,'눈싸라기','Powder Snow','얼음','Ice','Special',40,100,25,0,'allAdjacentFoes','Has a 10% chance to freeze the target.',0);
INSERT INTO moves VALUES(583,'파워젬','Power Gem','바위','Rock','Special',80,100,20,0,'normal','No additional effect.',1);
INSERT INTO moves VALUES(584,NULL,'Power Shift','노말','Normal','Status',0,NULL,12,0,'self','The user swaps its Attack and Defense stats, and stat stage changes remain on their respective stats. This move can be used again to swap the stats back. If the user uses Baton Pass, the replacement will have its Attack and Defense stats swapped if the effect is active. If the user has its stats recalculated by changing forme while its stats are swapped, this effect is ignored but is still active for the purposes of Baton Pass.',1);
INSERT INTO moves VALUES(585,'파워셰어','Power Split','에스퍼','Psychic','Status',0,NULL,12,0,'normal','The user and the target have their Attack and Special Attack stats set to be equal to the average of the user and the target''s Attack and Special Attack stats, respectively, rounded down. Stat stage changes are unaffected.',1);
INSERT INTO moves VALUES(586,'파워스웹','Power Swap','에스퍼','Psychic','Status',0,NULL,12,0,'normal','The user swaps its Attack and Special Attack stat stage changes with the target.',1);
INSERT INTO moves VALUES(587,'파워트릭','Power Trick','에스퍼','Psychic','Status',0,NULL,12,0,'self','The user swaps its Attack and Defense stats, and stat stage changes remain on their respective stats. This move can be used again to swap the stats back. If the user uses Baton Pass, the replacement will have its Attack and Defense stats swapped if the effect is active. If the user has its stats recalculated by changing forme while its stats are swapped, this effect is ignored but is still active for the purposes of Baton Pass.',1);
INSERT INTO moves VALUES(588,'기어오르기','Power Trip','악','Dark','Physical',20,100,12,0,'normal','Power is equal to 20+(X*20), where X is the user''s total stat stage changes that are greater than 0.',1);
INSERT INTO moves VALUES(589,'파워휩','Power Whip','풀','Grass','Physical',120,85,12,0,'normal','No additional effect.',1);
INSERT INTO moves VALUES(590,'그로우펀치','Power-Up Punch','격투','Fighting','Physical',40,100,20,0,'normal','Has a 100% chance to raise the user''s Attack by 1 stage.',0);
INSERT INTO moves VALUES(591,'단애의칼','Precipice Blades','땅','Ground','Physical',120,85,10,0,'allAdjacentFoes','No additional effect.',0);
INSERT INTO moves VALUES(592,'프레젠트','Present','노말','Normal','Physical',0,90,15,0,'normal','If this move is successful, it deals damage or heals the target. 40% chance for 40 power, 30% chance for 80 power, 10% chance for 120 power, and 20% chance to heal the target by 1/4 of its maximum HP, rounded down.',0);
INSERT INTO moves VALUES(593,'프리즘레이저','Prismatic Laser','에스퍼','Psychic','Special',160,100,10,0,'normal','If this move is successful, the user must recharge on the following turn and cannot select a move.',0);
INSERT INTO moves VALUES(594,'방어','Protect','노말','Normal','Status',0,NULL,8,4,'self','The user is protected from most attacks made by other Pokemon during this turn. This move has a 1/X chance of being successful, where X starts at 1 and triples each time this move is successfully used. X resets to 1 if this move fails, if the user''s last move used is not Baneful Bunker, Burning Bulwark, Detect, Endure, King''s Shield, Max Guard, Obstruct, Protect, Quick Guard, Silk Trap, Spiky Shield, or Wide Guard, or if it was one of those moves and the user''s protection was broken. Fails if the user moves last this turn.',1);
INSERT INTO moves VALUES(595,'환상빔','Psybeam','에스퍼','Psychic','Special',65,100,20,0,'normal','Has a 10% chance to confuse the target.',0);
INSERT INTO moves VALUES(596,'사이코블레이드','Psyblade','에스퍼','Psychic','Physical',80,100,15,0,'normal','If the current terrain is Electric Terrain, this move''s power is multiplied by 1.5.',0);
