INSERT INTO moves VALUES(598,'사이코키네시스','Psychic','에스퍼','Psychic','Special',90,100,12,0,'normal','Has a 10% chance to lower the target''s Special Defense by 1 stage.',1);
INSERT INTO moves VALUES(599,'사이코팽','Psychic Fangs','에스퍼','Psychic','Physical',85,100,12,0,'normal','If this attack does not miss, the effects of Reflect, Light Screen, and Aurora Veil end for the target''s side of the field before damage is calculated.',1);
INSERT INTO moves VALUES(600,'사이코노이즈','Psychic Noise','에스퍼','Psychic','Special',75,100,12,0,'normal','For 2 turns, the target is prevented from restoring any HP as long as it remains active. During the effect, healing and draining moves are unusable, and Abilities and items that grant healing will not heal the user. If an affected Pokemon uses Baton Pass, the replacement will remain unable to restore its HP. Pain Split and the Regenerator Ability are unaffected.',1);
INSERT INTO moves VALUES(601,'사이코필드','Psychic Terrain','에스퍼','Psychic','Status',0,NULL,12,0,'all','For 5 turns, the terrain becomes Psychic Terrain. During the effect, the power of Psychic-type attacks made by grounded Pokemon is multiplied by 1.3 and grounded Pokemon cannot be hit by moves with priority greater than 0, unless the target is an ally. Camouflage transforms the user into a Psychic type, Nature Power becomes Psychic, and Secret Power has a 30% chance to lower the target''s Speed by 1 stage. Fails if the current terrain is Psychic Terrain.',1);
INSERT INTO moves VALUES(602,'사이코부스트','Psycho Boost','에스퍼','Psychic','Special',140,90,5,0,'normal','Lowers the user''s Special Attack by 2 stages.',0);
