INSERT INTO moves VALUES(604,'사이코시프트','Psycho Shift','에스퍼','Psychic','Status',0,100,10,0,'normal','The user''s non-volatile status condition is transferred to the target, and the user is then cured. Fails if the user has no non-volatile status condition or if the target already has one.',0);
