INSERT INTO moves VALUES(636,'잠재댄스','Revelation Dance','노말','Normal','Special',90,100,15,0,'normal','This move''s type depends on the user''s primary type. If the user''s primary type is typeless, this move''s type is the user''s secondary type if it has one, otherwise the added type from Forest''s Curse or Trick-or-Treat. This move is typeless if the user''s type is typeless alone.',0);
INSERT INTO moves VALUES(637,'리벤지','Revenge','격투','Fighting','Physical',60,100,10,-4,'normal','Power doubles if the user was hit by the target this turn.',0);
INSERT INTO moves VALUES(638,'기사회생','Reversal','격투','Fighting','Physical',0,100,16,0,'normal','The power of this move is 20 if X is 33 to 48, 40 if X is 17 to 32, 80 if X is 10 to 16, 100 if X is 5 to 9, 150 if X is 2 to 4, and 200 if X is 0 or 1, where X is equal to (user''s current HP * 48 / user''s maximum HP), rounded down.',1);
INSERT INTO moves VALUES(639,NULL,'Revival Blessing','노말','Normal','Status',0,1,1,0,'self','A fainted party member is selected and revived with 1/2 its max HP, rounded down. Fails if there are no fainted party members.',0);
