INSERT INTO moves VALUES(641,'울부짖기','Roar','노말','Normal','Status',0,NULL,20,-6,'normal','The target is forced to switch out and be replaced with a random unfainted ally. Fails if the target is the last unfainted Pokemon in its party, or if the target used Ingrain previously or has the Suction Cups Ability.',1);
