INSERT INTO moves VALUES(686,NULL,'Shadow Strike',NULL,NULL,'Physical',80,95,10,0,'normal','Has a 50% chance to lower the target''s Defense by 1 stage.',0);
INSERT INTO moves VALUES(687,'각지기','Sharpen','노말','Normal','Status',0,1,30,0,'self','Raises the user''s Attack by 1 stage.',0);
INSERT INTO moves VALUES(688,NULL,'Shed Tail','노말','Normal','Status',0,NULL,12,0,'self','The user takes 1/2 of its maximum HP, rounded up, and creates a substitute that has 1/4 of the user''s maximum HP, rounded down. The user is replaced with another Pokemon in its party and the selected Pokemon has the substitute transferred to it. Fails if the user would faint, or if there are no unfainted party members.',1);
INSERT INTO moves VALUES(689,'절대영도','Sheer Cold','얼음','Ice','Special',0,30,8,0,'normal','Deals damage to the target equal to the target''s maximum HP. Ignores accuracy and evasiveness modifiers. This attack''s accuracy is equal to (user''s level - target''s level + X)%, where X is 30 if the user is an Ice type and 20 otherwise, and fails if the target is at a higher level. Ice-type Pokemon and Pokemon with the Sturdy Ability are immune.',1);
INSERT INTO moves VALUES(690,'셸암즈','Shell Side Arm','독','Poison','Special',90,100,12,0,'normal','Has a 20% chance to poison the target. This move becomes a physical attack that makes contact if the value of ((((2 * the user''s level / 5 + 2) * 90 * X) / Y) / 50), where X is the user''s Attack stat and Y is the target''s Defense stat, is greater than the same value where X is the user''s Special Attack stat and Y is the target''s Special Defense stat. No stat modifiers other than stat stage changes are considered for this purpose. If the two values are equal, this move chooses a damage category at random.',1);
INSERT INTO moves VALUES(691,'껍질깨기','Shell Smash','노말','Normal','Status',0,NULL,16,0,'self','Lowers the user''s Defense and Special Defense by 1 stage. Raises the user''s Attack, Special Attack, and Speed by 2 stages.',1);
INSERT INTO moves VALUES(692,'트랩셸','Shell Trap','불꽃','Fire','Special',150,100,5,-3,'allAdjacentFoes','Fails unless the user is hit by a physical attack from an opponent this turn before it can execute the move. If the user was hit and has not fainted, it attacks immediately after being hit, and the effect ends. If the opponent''s physical attack had a secondary effect removed by the Sheer Force Ability, it does not count for the purposes of this effect.',0);
