INSERT INTO moves VALUES(787,'수류연타','Surging Strikes','물','Water','Physical',25,100,5,0,'normal','Hits three times. This move is always a critical hit unless the target is under the effect of Lucky Chant or has the Battle Armor or Shell Armor Abilities.',0);
INSERT INTO moves VALUES(788,'뽐내기','Swagger','노말','Normal','Status',0,85,16,0,'normal','Raises the target''s Attack by 2 stages and confuses it.',1);
INSERT INTO moves VALUES(789,'꿀꺽','Swallow','노말','Normal','Status',0,NULL,12,0,'self','The user restores its HP based on its Stockpile count. Restores 1/4 of its maximum HP if it''s 1, 1/2 of its maximum HP if it''s 2, both rounded half down, and all of its HP if it''s 3. Fails if the user''s Stockpile count is 0. The user''s Defense and Special Defense decrease by as many stages as Stockpile had increased them, and the user''s Stockpile count resets to 0.',1);
