INSERT INTO moves VALUES(791,'달콤한향기','Sweet Scent','노말','Normal','Status',0,100,20,0,'allAdjacentFoes','Lowers the target''s evasiveness by 2 stages.',1);
INSERT INTO moves VALUES(792,'스피드스타','Swift','노말','Normal','Special',60,1,20,0,'allAdjacentFoes','This move does not check accuracy.',0);
INSERT INTO moves VALUES(793,'바꿔치기','Switcheroo','악','Dark','Status',0,100,12,0,'normal','The user swaps its held item with the target''s held item. Fails if either the user or the target is holding a Mail or Z-Crystal, if neither is holding an item, if the user is trying to give or take a Mega Stone to or from the species that can Mega Evolve with it, or if the user is trying to give or take a Blue Orb, a Red Orb, a Griseous Orb, a Plate, a Drive, or a Memory to or from a Kyogre, a Groudon, a Giratina, an Arceus, a Genesect, or a Silvally, respectively. The target is immune to this move if it has the Sticky Hold Ability.',1);
INSERT INTO moves VALUES(794,'칼춤','Swords Dance','노말','Normal','Status',0,NULL,20,0,'self','Raises the user''s Attack by 2 stages.',1);
INSERT INTO moves VALUES(795,'싱크로노이즈','Synchronoise','에스퍼','Psychic','Special',120,100,10,0,'allAdjacent','The target is immune if it does not share a type with the user.',0);
INSERT INTO moves VALUES(796,'광합성','Synthesis','풀','Grass','Status',0,NULL,8,0,'self','The user restores 1/2 of its maximum HP if Delta Stream or no weather conditions are in effect or if the user is holding Utility Umbrella, 2/3 of its maximum HP if the weather is Desolate Land or Sunny Day, and 1/4 of its maximum HP if the weather is Primordial Sea, Rain Dance, Sandstorm, or Snow, all rounded half down.',1);
INSERT INTO moves VALUES(797,NULL,'Syrup Bomb','풀','Grass','Special',60,90,12,0,'normal','If this move is successful, it causes the target''s Speed to be lowered by 1 stage at the end of each turn for 3 turns.',1);
