INSERT INTO moves VALUES(804,'돌진','Take Down','노말','Normal','Physical',90,85,20,0,'normal','If the target lost HP, the user takes recoil damage equal to 1/4 the HP lost by the target, rounded half up, but not less than 1 HP.',0);
INSERT INTO moves VALUES(805,NULL,'Take Heart','에스퍼','Psychic','Status',0,1,15,0,'self','The user cures its non-volatile status condition. Raises the user''s Special Attack and Special Defense by 1 stage.',0);
